const clientId = $('Validate Input').first().json.clientId;
const claudeResponse = $('Call Claude API').first().json;
const body = claudeResponse.body || claudeResponse;

let auditData;
try {
  const text = body.content?.[0]?.text || '{}';
  // Remove any markdown code fences if present
  const cleaned = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  auditData = JSON.parse(cleaned);
} catch (e) {
  auditData = {
    status: 'YELLOW',
    error: 'Failed to parse Claude response',
    rawResponse: body.content?.[0]?.text || 'No response'
  };
}

return [{
  json: {
    success: true,
    clientId,
    auditDate: new Date().toISOString(),
    result: auditData
  }
}];
